<section class="card"><div class="card-header card-no-border"><div class="header-top"><div><h2>درخواست‌های برداشت افیلیت</h2><small>پرداخت بانکی را خارج از سامانه انجام دهید و سپس وضعیت را ثبت کنید.</small></div><a class="btn secondary" href="<?= e(url('plugin/affiliate/admin')) ?>">تنظیم سناریوها</a></div></div>
  <div class="card-body pt-0"><nav class="proma-contract-tabs"><a class="<?= $status === 'pending' ? 'active' : '' ?>" href="<?= e(url('plugin/affiliate/withdrawals', ['status'=>'pending'])) ?>">در انتظار بررسی</a><a class="<?= $status === 'approved' ? 'active' : '' ?>" href="<?= e(url('plugin/affiliate/withdrawals', ['status'=>'approved'])) ?>">تأییدشده</a><a class="<?= $status === 'paid' ? 'active' : '' ?>" href="<?= e(url('plugin/affiliate/withdrawals', ['status'=>'paid'])) ?>">پرداخت‌شده</a><a class="<?= $status === 'rejected' ? 'active' : '' ?>" href="<?= e(url('plugin/affiliate/withdrawals', ['status'=>'rejected'])) ?>">ردشده</a></nav>
    <div class="table-wrap"><table><thead><tr><th scope="col">معرف</th><th scope="col">مبلغ</th><th scope="col">اطلاعات پرداخت</th><th scope="col">درخواست</th><th scope="col">یادداشت مشتری</th><th scope="col">رسیدگی</th></tr></thead><tbody>
    <?php foreach (($withdrawals ?? []) as $item): ?><tr><td><?= e($item['full_name']) ?><br><?= e(to_persian_digits($item['mobile'])) ?></td><td><?= money_toman($item['amount_toman']) ?></td><td><?= e($item['payee_name']) ?><br><?php if (!empty($item['card_number'])): ?><small>کارت <span dir="ltr"><?= e(to_persian_digits($item['card_number'])) ?></span></small><br><?php endif; ?><?php if (!empty($item['account_number'])): ?><small>حساب <span dir="ltr"><?= e(to_persian_digits($item['account_number'])) ?></span></small><br><?php endif; ?><?php if (!empty($item['iban'])): ?><small>شبا <span dir="ltr"><?= e($item['iban']) ?></span></small><?php endif; ?></td><td><?= e(jdatetime($item['created_at'])) ?></td><td><?= e($item['request_note'] ?? '—') ?></td><td><?php if (in_array($status, ['pending','approved'], true)): ?><form method="post" action="<?= e(url('plugin/affiliate/withdrawals/' . (int) $item['id'], ['status' => $status])) ?>" class="form-grid"><?= csrf_field() ?><input name="review_note" maxlength="500" placeholder="یادداشت رسیدگی"><div class="actions"><?php if ($status === 'pending'): ?><button class="btn small success" name="decision" value="approved" type="submit">تأیید درخواست</button><?php else: ?><button class="btn small success" name="decision" value="paid" type="submit">ثبت پرداخت</button><?php endif; ?><button class="btn small danger" name="decision" value="rejected" type="submit">رد درخواست</button></div></form><?php else: ?><span><?= e($item['review_note'] ?? '—') ?></span><?php endif; ?></td></tr><?php endforeach; ?>
    <?php if (empty($withdrawals)): ?><tr><td colspan="6" class="empty">درخواستی در این وضعیت وجود ندارد.</td></tr><?php endif; ?></tbody></table></div>
  </div>
</section>
